// Worker entry (wrangler.jsonc "main"). Wraps the OpenNext handler generated in .open-next/ with the edge
// rules in lib/edge.ts (Cloudflare review of 2026-09-27, plan U1/U3/U4/U5).
// Keep this file tiny: it runs on every request and counts against the Workers Free CPU limit.

// @ts-ignore -- generated by `opennextjs-cloudflare build`; absent until the first build.
import { default as handler } from "./.open-next/worker.js";
// @ts-ignore -- generated by scripts/prebuilt-pages.mjs after the OpenNext build (CLEAR row 43).
import prebuiltPages from "./.open-next/prebuilt-pages.mjs";
import { advisorNoindex, canonicalRedirect, htmlCacheControl, journeyRedirect, prebuiltAsset, SECURITY_HEADERS, type PrebuiltPage } from "./lib/edge";

interface EdgeEnv {
  /** Set to "1" in .dev.vars only: local preview presents requests as http://unlimitinsure.com. */
  DISABLE_CANONICAL_REDIRECT?: string;
  /** "1" while no insurance products are published: old journey pages redirect here (CLEAR row 41). Remove when products go live. */
  JOURNEY_REDIRECTS?: string;
  PURCHASE_ENABLED?: string;
  ASSETS: { fetch(input: Request | URL | string): Promise<Response> };
}

const PAGES = prebuiltPages as Record<string, PrebuiltPage>;

export default {
  async fetch(request: Request, env: EdgeEnv, ctx: ExecutionContext): Promise<Response> {
    if (env.DISABLE_CANONICAL_REDIRECT !== "1") {
      const to = canonicalRedirect(new URL(request.url));
      if (to) return Response.redirect(to, 301);
    }

    const j = journeyRedirect(request, { journeyRedirects: env.JOURNEY_REDIRECTS === "1", purchaseEnabled: env.PURCHASE_ENABLED === "true" });
    if (j) {
      const r = new Response(null, { status: j.status, headers: { Location: j.location, "Cache-Control": "private, no-cache, no-store, max-age=0, must-revalidate" } });
      for (const [k, v] of Object.entries(SECURITY_HEADERS)) r.headers.set(k, v);
      return r;
    }

    // Prebuilt pages: stream the files Next.js wrote instead of OpenNext's cache entry (CLEAR row 43).
    const pre = prebuiltAsset(request, PAGES);
    let res: Response | null = null;
    if (pre) {
      const a = await env.ASSETS.fetch(new URL(pre.asset, request.url));
      if (a.ok) res = new Response(request.method === "HEAD" ? null : a.body, { status: 200, headers: pre.headers });
      else await a.body?.cancel();
    }
    res ??= (await handler.fetch(request, env, ctx)) as Response;
    const out = new Response(res.body, res);
    for (const [k, v] of Object.entries(SECURITY_HEADERS)) out.headers.set(k, v);
    const cc = htmlCacheControl(out.headers.get("content-type"), out.headers.get("cache-control"));
    if (cc) out.headers.set("Cache-Control", cc);
    if (advisorNoindex(new URL(request.url))) out.headers.set("X-Robots-Tag", "noindex");
    return out;
  },
};
